class TestRunner
{
   public static void main(String[] args) throws java.lang.Exception
   {     

     
     TestResult[] test_results = EdTestRunner.executeTests();
     String output = "<__educative_test_results__>{\"test_results\": [";

     int count = 0;
     for(TestResult result : test_results) {
       if (count > 0) {
         output += ",";
       }
       output += "{";
       output += "\"reason\": \"" + result.reason + "\",";
       output += "\"input\": \"" + result.input + "\",";
       output += "\"expected_output\": \"" + result.expected_output + "\",";
       output += "\"actual_output\": \"" + result.actual_output + "\",";
       output += "\"succeeded\": " + (result.succeeded ? "true" : "false") + "}";
       count++;
     }


    output += "]}</__educative_test_results__>";

    System.out.println(output);
  }
}
